mapper.select:
select t1.id as id, t1.material_code as materialCode, t3.site_name as stackName, t1.maintence_style as maintenceStyle, t2.phases as phases, t2.id as stageId, t2.created_time as createdTime from tb_maintain_plan t1 left join tb_maintain_plan_stage t2 on t1.stage_id = t2.id inner join (select id,site_name from tb_stack where 1=1 and pid_route like concat('%',#{maintainPlanDto.pidRoute},'%') and id = #{maintainPlanDto.stackId} ) t3 on t3.id = t1.stack_id
t1.is_end = '0' and t2.aftercare_date_end >= #{maintainPlanDto.nowDate} and t2.is_change = '0'
and t1.material_code like concat('%',#{maintainPlanDto.materialCode},'%')
and t2.created_time >= #{maintainPlanDto.startTime}
and t2.created_time <= #{maintainPlanDto.endTime}
and t2.phases = #{maintainPlanDto.phases}
and t1.maintence_style = #{maintainPlanDto.maintenceStyle}
order by created_time desc

mapper.update:
update tb_maintain_plan

    maintence_style= #{maintainPlanDto.maintenceStyle},
    material_code= #{maintainPlanDto.materialCode},
    principal_ids = #{maintainPlanDto.principalId}

where id = #{maintainPlanDto.id}

update tb_maintain_plan_stage
maintain_days = #{maintainPlanDto.maintainDays}, aftercare_date_start = #{maintainPlanDto.aftercareDateStart}, aftercare_date_end = #{maintainPlanDto.aftercareDateEnd}, maintain_count = #{maintainPlanDto.maintainCount}, oxygen_reduction_day = #{maintainPlanDto.oxygenReductionTime}, expire_time = #{maintainPlanDto.expireTime}, phases=#{maintainPlanDto.phases}, update_user = #{maintainPlanDto.updateUser}, updated_time = #{maintainPlanDto.updatedTime}
where maintain_plan_id = #{maintainPlanDto.id} and is_change = '0'

