select t1.id as id, t1.material_code as materialCode, t3.site_name as stackName, t1.maintence_style as maintenceStyle, t2.phases as phases, t2.maintain_count as maintainCount, t2.id as stageId, t2.maintain_days as maintainDays, t2.aftercare_date_end as aftercareDateEnd from tb_maintain_plan t1 left join tb_maintain_plan_stage t2 on t1.stage_id = t2.id inner join (select id,site_name from tb_stack and pid_route like concat('%',#{maintainPlanDto.pidRoute},'%') and id = #{maintainPlanDto.stackId}
) t3 on t3.id = t1.stack_id
