mapper.update:
 update tb_maintain_count set
 stack_id = #{maintainPlanDto.stackId},area_id = #{maintainPlanDto.areaId},floor_id = #{maintainPlanDto.floorId},
 buliding_id = #{maintainPlanDto.buildingId} ,warehouse_id = #{maintainPlanDto.warehouseId}
where maintain_plan_id = #{maintainPlanDto.id}

mapper.select:
SELECT substring_index(group_concat(t.id),',',1) as id,t.material_code as materialCode,SUM(t.maintain_count) as maintainCount,
a.site_name as stackName,substring_index(group_concat(t.created_time),',',1) as createdTime,
t.warehouse_id as warehouseId,substring_index(group_concat(t.buliding_id),',',1) as buildingId
FROM tb_maintain_count t
inner join tb_warehouse a on a.id = t.warehouse_id
WHERE 1=1
and t.material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and t.maintence_style = #{maintainCountDto.maintenceStyle}
 and t.phases = #{maintainCountDto.phases}
 and t.created_time >= #{maintainCountDto.startTime}
 and t.created_time <= #{maintainCountDto.endTime}
GROUP BY t.material_code,t.warehouse_id,stackName order by t.material_code,t.warehouse_id

SELECT substring_index(group_concat(t.id),',',1) as id,t.material_code as materialCode,SUM(t.maintain_count) as maintainCount,
    a.site_name as stackName,substring_index(group_concat(t.created_time),',',1) as createdTime,
    t.buliding_id as buildingId,t.warehouse_id as warehouseId,substring_index(group_concat(t.floor_id),',',1) as floorId
    FROM tb_maintain_count t
    inner join tb_building a on a.id = t.buliding_id
WHERE 1=1
and t.buliding_id in  #{id}  
and t.material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and t.maintence_style = #{maintainCountDto.maintenceStyle}
 and t.phases = #{maintainCountDto.phases}
 and t1.created_time >= #{maintainCountDto.startTime}
 and t1.created_time <= #{maintainCountDto.endTime}
GROUP BY t.material_code,t.warehouse_id,t.buliding_id,stackName order by t.material_code,t.warehouse_id,t.buliding_id

SELECT substring_index(group_concat(t.id),',',1) as id,t.material_code as materialCode,SUM(t.maintain_count) as maintainCount,
a.site_name as stackName,substring_index(group_concat(t.created_time),',',1) as createdTime,
t.floor_id as floorId,t.buliding_id as buildingId,substring_index(group_concat(t.area_id),',',1) as areaId
FROM tb_maintain_count t
inner join tb_floor a on a.id = t.floor_id
WHERE 1=1
and t.floor_id in  #{id}  
and t.material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and t.maintence_style = #{maintainCountDto.maintenceStyle}
 and t.phases = #{maintainCountDto.phases}
 and t.created_time >= #{maintainCountDto.startTime}
 and t.created_time <= #{maintainCountDto.endTime}
GROUP BY t.material_code,t.warehouse_id,t.buliding_id,t.floor_id,stackName order by t.material_code,t.warehouse_id,t.buliding_id,t.floor_id

SELECT substring_index(group_concat(t.id),',',1) as id,t.material_code as materialCode,SUM(t.maintain_count) as maintainCount,
a.site_name as stackName,substring_index(group_concat(t.created_time),',',1) as createdTime,
t.area_id as areaId,t.floor_id as floorId,substring_index(group_concat(t.stack_id),',',1) as stackId
FROM tb_maintain_count t
inner join tb_ware_area a on a.id = t.area_id
WHERE 1=1
and t.area_id in  #{id}  
and t.material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and t.maintence_style = #{maintainCountDto.maintenceStyle}
 and t.phases = #{maintainCountDto.phases}
 and t.created_time >= #{maintainCountDto.startTime}
 and t.created_time <= #{maintainCountDto.endTime}
GROUP BY t.material_code,t.warehouse_id,t.buliding_id,t.floor_id,t.area_id,stackName order by t.material_code,t.warehouse_id,t.buliding_id,t.floor_id,t.area_id

SELECT substring_index(group_concat(t.id),',',1) as id,t.material_code as materialCode,SUM(t.maintain_count) as maintainCount,a.site_name as stackName,
substring_index(group_concat(t.created_time),',',1) as createdTime,
substring_index(group_concat(t.maintence_style),',',1) as maintenceStyle,
substring_index(group_concat(t.phases),',',1) as phases,
t.area_id as areaId,
t.stack_id as stackId
FROM tb_maintain_count t
inner join tb_stack a on a.id = t.stack_id
WHERE 1=1
and t.stack_id in  #{id}  
and t.material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and t.maintence_style = #{maintainCountDto.maintenceStyle}
 and t.phases = #{maintainCountDto.phases}
 and t.created_time >= #{maintainCountDto.startTime}
 and t.created_time <= #{maintainCountDto.endTime}
GROUP BY t.material_code,t.warehouse_id,t.buliding_id,t.floor_id,t.area_id,t.stack_id,stackName order by t.material_code,t.warehouse_id,t.buliding_id,t.floor_id,t.area_id,t.stack_id

